actual_lines = []
for line in lines_raw:
    idx = line.index('\t') if '\t' in line else -1
    if idx >= 0:
        actual_lines.append(line[idx+1:])
    else:
        actual_lines.append(line)

# Look for import statements, class definitions, function definitions at column 0
for i, line in enumerate(actual_lines):
    stripped = line.strip()
    # Skip empty lines and comments
    if not stripped or stripped.startswith('#'):
        continue
    # Check if it's at the start of a line (no indentation)
    if not line[0].isspace():
        print(f"Line {i+1}: {line[:80]}")
